class Solution {
public:
    string getHint(string secret, string guess) {
        int bulls = 0;
        vector<int> sCnt(10, 0), gCnt(10, 0);
        for (int i = 0; i < (int)secret.size(); i++) {
            if (secret[i] == guess[i]) {
                bulls++;
            } else {
                sCnt[secret[i] - '0']++;
                gCnt[guess[i] - '0']++;
            }
        }
        int cows = 0;
        for (int d = 0; d < 10; d++) {
            cows += min(sCnt[d], gCnt[d]);
        }
        return to_string(bulls) + "A" + to_string(cows) + "B";
    }
};

class Solution {
    public String getHint(String secret, String guess) {
        int bulls = 0;
        int[] sCnt = new int[10];
        int[] gCnt = new int[10];
        for (int i = 0; i < secret.length(); i++) {
            char s = secret.charAt(i), g = guess.charAt(i);
            if (s == g) {
                bulls++;
            } else {
                sCnt[s - '0']++;
                gCnt[g - '0']++;
            }
        }
        int cows = 0;
        for (int d = 0; d < 10; d++) {
            cows += Math.min(sCnt[d], gCnt[d]);
        }
        return bulls + "A" + cows + "B";
    }
}

